boolean dfs(char[][] g, String w, int k, int r, int c) {
    if (k == w.length()) return true;
    if (r < 0 || c < 0 || r >= g.length || c >= g[0].length
            || g[r][c] != w.charAt(k)) return false;
    g[r][c] = '#';                          // never restored
    return dfs(g, w, k + 1, r + 1, c) || dfs(g, w, k + 1, r - 1, c)
        || dfs(g, w, k + 1, r, c + 1) || dfs(g, w, k + 1, r, c - 1);
}
